bool __cdecl Cmd_ToggleCastShadows_Execute(const ScriptParameter* apParameters, const char* apCompiledParams, TESObjectREFR* apRefObject, TESObjectREFR* apContainer, Script* apScript, ScriptLocals* apScriptLocals, double& afReturnValue, unsigned int& auiOffset)
{
    int iWhichType = 0;
    if (!ExtractArgs(apParameters, apCompiledParams, &auiOffset, apRefObject, apContainer, apScript, apScriptLocals, &iWhichType))
        return false;
    if (iWhichType < 0 || iWhichType > 6) {
        if (g_bConsoleEcho)
            _DebugLog("Shadow object type must be [0,6]");
        return true;
    }
    if ((1 << iWhichType) & DAT_011ad82c)
        DAT_011ad82c &= ~(1 << iWhichType);
    else
        DAT_011ad82c |= (1 << iWhichType);
    if (g_bConsoleEcho) {
        char* ptypetotext[7] = { "Undetermined", "Architecture", "Furniture", "Actors", "Items", (char*)g_011d28a4_arg1, "Other" };
        char* ptypetext = ptypetotext[iWhichType];
        _DebugLog("Shadows %s: %s", ptypetext, ((1 << iWhichType) & DAT_011ad82c) ? "On" : "Off");
    }
    return true;
}

