bool Cmd_ToggleCellNode_Execute(const ScriptParameter* parameters, const char* scriptData, TESObjectREFR* thisObject, TESObjectREFR* container, Script* script, ScriptLocals* locals, double* result, unsigned int* opcodeOffset)
{
    unsigned int nodeIndex = -1;
    if (!ExtractArgs(parameters, scriptData, opcodeOffset, thisObject, container, script, locals, &nodeIndex))
        return false;
    if (nodeIndex != -1) {
        const char* nodeName = 0;
        switch (nodeIndex) {
        case 0: nodeName = "Actor"; break;
        case 1: nodeName = "Marker"; break;
        case 2: nodeName = "Land"; break;
        case 3: nodeName = "Static"; break;
        case 4: nodeName = "Dynamic"; break;
        case 5: nodeName = "MultiBound"; break;
        case 6: nodeName = "Water"; break;
        }
        if (nodeName) {
            bool culled = GetCellNodeCulled(nodeIndex);
            g_pTESStub->SetCellNodeCulled(nodeIndex, culled, 0);
            if (nodeIndex == 6 && g_pTESStub->GetWaterSystem())
                g_pTESStub->GetWaterSystem()->SetCulled(culled, 0, 0);
            DebugLog("Cell %s nodes now %s.", nodeName, culled ? "DISPLAYED" : "CULLED");
        } else {
            DebugLog("Invalid node index. (0-6).");
        }
    }
    return true;
}

