bool Cmd_Look_Execute(const ScriptParameter* paramInfo, const char* scriptData, TESObjectREFR* thisObj, TESObjectREFR* containingObj, Script* scriptObj, ScriptLocals* locals, double& result, unsigned int& opcodeOffsetPtr)
{
    RefVT* pItem = 0;
    int iFlag = 0;
    if (!ExtractArgs(paramInfo, scriptData, &opcodeOffsetPtr, thisObj, containingObj, scriptObj, locals, &pItem, &iFlag))
        return false;
    if (thisObj && pItem) {
        ActorVT* pActor = (ActorVT*)dynamic_cast<Actor*>(thisObj);
        if (pActor && pActor->GetCurrentProcess()) {
            if (!iFlag) {
                ProcessVT* pProcess = pActor->GetCurrentProcess();
                pProcess->RemoveItem(pItem);
                pActor->BSFile_GetDevice()->ExtraDataList_SetHeadTrackTargetExtra(pItem);
            } else {
                pActor->Actor_SetLookAtTarget(*pItem->GetPos());
                ProcessVT* pProc = pActor->GetCurrentProcess();
                pProc->AddItem(pItem);
                pItem->TESObjectREFR_SetTargeted(true);
            }
            pActor->MarkChanged(0x80000000);
        }
    }
    return true;
}

