                    reinterpret_cast<AIProcess*>(static_cast<const Actor*>(actor)->GetCurrentProcess())->SetIdle(idle);
                    reinterpret_cast<AIProcess*>(static_cast<const Actor*>(actor)->GetCurrentProcess())->SetFlag(0x80);
