    Actor* pActor = dynamic_cast<Actor*>(apRefObject);
    if (!ExtractArgs(apParameters, apCompiledParams, &auiOffset, apRefObject, apContainer, apScript, apScriptLocals, &fDuration)) {
        return false;
    }
